before:
import { test, expect } from "@playwright/test";

   const baseUrl = "https://teskerti.tn";

   test.describe("Visualisation des détails d'un événement", () => {
     test("Affichage des informations de base de l'événement", async ({ page }) => {
       // Given: l'utilisateur est sur la fiche détaillée d'un événement
       await page.goto(baseUrl + "/evenement/cairokee-carthage");

       // Then: le titre de l'événement est affiché
       await expect(page.locator(".col-md-8 h1").first()).toBeVisible();

       // And: la date et l'heure de l'événement sont affichées
       await expect(page.locator("#main-ticket-form label").first()).toBeVisible();

       // And: le lieu (salle) de l'événement est affiché
       // TODO: Selector for venue/location not explicitly provided in knownSelectors
       await expect(page.locator(".venue, .lieu, [class*=\"salle\"]").first()).toBeVisible();
     });
   });

